query FlxChatbotConversationList($filter: FlxChatbotConversationFilter, $search: String, $first: Int = 50) {
  flxChatbotConversations(filter: $filter, search: $search, first: $first) {
    nodes {
      ...FlxChatbotConversationRow
    }
    pageInfo {
      hasNextPage
      endCursor
    }
    totalCount
  }
}

fragment FlxChatbotConversationRow on FlxChatbotConversation {
  id
  databaseId
  title
  name
  email
  phone
  status
  unread
  rating
  ratingNote
  isLead
  orderId
  orderUrl
  pageUrl
  pageTitle
  userId
  agentName
  fluxChatUrl
  summary
  lastActivity {
    timestamp
    label
    relative
  }
  online
  typing
  lastMessage {
    role
    body
  }
}

